### 6.5 Combining Bullet Chart and Sparklines

Finally, I will bring in the budget target data and combine the bullet chart and sparklines into a single dashboard-style table.


::: {.cell}

```{.r .cell-code}
bullet <- coffeechain %>%
  filter(Date >= "2013-01-01") %>%
  group_by(`Product`) %>%
  summarise(`Target` = sum(`Budget Sales`),
            `Actual` = sum(`Sales`)) %>%
  ungroup()

sales_data <- sales_data %>%
  left_join(bullet)
```
:::



::: {.cell}

```{.r .cell-code}
sales_data %>%
  gt() %>%
  gt_plt_sparkline('Monthly Sales',
                   same_limit = FALSE) %>%
  gt_plt_bullet(column = Actual,
                target = Target,
                width = 28,
                palette = c("lightblue", "black")) %>%
  gt_theme_538() %>%
  cols_width(
    Product ~ pct(24),
    Min ~ pct(14),
    Max ~ pct(14),
    Average ~ pct(16),
    `Monthly Sales` ~ pct(18),
    Actual ~ pct(14)
  ) %>%
  tab_options(table.width = pct(100))
```

